DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.reconcile_bank_transactions(jsonb)'::regprocedure) INTO definition; definition:=replace(definition,'comp text; value numeric;','comp text; allocation_amount numeric;'); definition:=regexp_replace(definition,'(?<![.a-z_])value(?![a-z_])','allocation_amount','g'); definition:=replace(definition,'e(allocation_amount,ord)','e(value,ord)'); EXECUTE definition; END $$;